  quoteTh: "บางครั้ง การมีคนรับฟังอย่างจริงใจ ก็ทำให้เรากล้าที่จะเป็นตัวเอง",
  quoteZh: "有时候，有人真诚地倾听，就能让我们勇敢地做自己。",
  quotePinyin: "Yǒu shíhou, yǒu rén zhēnchéng de qīngtīng, jiù néng ràng wǒmen yǒnggǎn de zuò zìjǐ。"
