  quoteTh: "เพื่อนที่ดีอาจไม่ได้แก้ปัญหาให้เรา แต่ทำให้เราไม่ต้องเผชิญปัญหาเพียงลำพัง",
  quoteZh: "好朋友不一定能帮我们解决问题，但能让我们不必独自面对困难。",
  quotePinyin: "Hǎo péngyou bù yídìng néng bāng wǒmen jiějué wèntí, dàn néng ràng wǒmen bú bì dúzì miànduì kùnnan。"
