  quoteTh: "ความกล้าไม่ใช่การไม่กลัว แต่คือการก้าวไปข้างหน้าทั้งที่ยังกลัวอยู่",
  quoteZh: "勇敢不是不害怕，而是即使害怕，也愿意向前迈进。",
