  quoteTh: "คนที่อยู่ข้างเราอาจไม่ได้ทำให้ความกลัวหายไป แต่ช่วยให้เรากล้าเผชิญหน้ากับมัน",
  quoteZh: "真正的陪伴，不是让你不再害怕，而是让你有勇气面对自己的恐惧。",
