  quoteTh: "เราไม่จำเป็นต้องเดินบนเส้นทางเดียวกัน ก็สามารถสนับสนุนความฝันของกันและกันได้",

  quoteZh: "我们不一定要走同一条路，也可以互相支持。",

  quotePinyin: "Wǒmen bù yídìng yào zǒu tóng yì tiáo lù, yě kěyǐ hùxiāng zhīchí。"
