  quoteTh: "บางครั้งความเงียบไม่ได้ทำให้เราเข้าใจกันมากขึ้น แต่ความกล้าที่จะพูดความจริงอาจช่วยรักษาความสัมพันธ์ไว้ได้",

  quoteZh: "有时候，沉默不能让彼此更理解，勇敢地说出真心话才能守护关系。",

  quotePinyin: "Yǒu shíhou, chénmò bù néng ràng bǐcǐ gèng lǐjiě, yǒnggǎn de shuō chū zhēnxīnhuà cái néng shǒuhù guānxì。"
