  quoteTh: "คำขอโทษที่จริงใจไม่ใช่แค่การพูดว่าเสียใจ แต่คือการยอมรับความผิดและพยายามเปลี่ยนแปลงตัวเอง",

  quoteZh: "真诚的道歉不只是说对不起，还要承认错误，努力改变自己。",

  quotePinyin: "Zhēnchéng de dàoqiàn bù zhǐ shì shuō duìbuqǐ, hái yào chéngrèn cuòwù, nǔlì gǎibiàn zìjǐ。"
