  quoteTh: "ผลลัพธ์เป็นเพียงส่วนหนึ่งของการเดินทาง ความพยายามและกำลังใจก็มีความหมายเช่นกัน",

  quoteZh: "结果只是成长过程中的一部分，努力和鼓励同样重要。",

  quotePinyin: "Jiéguǒ zhǐ shì chéngzhǎng guòchéng zhōng de yí bùfen, nǔlì hé gǔlì tóngyàng zhòngyào。"
