  quoteTh: "เราอาจควบคุมผลลัพธ์ไม่ได้ทุกอย่าง แต่เราเลือกได้ว่าจะเรียนรู้อะไรจากมัน",

  quoteZh: "我们也许不能控制所有结果，但是可以选择从结果中学到什么。",

  quotePinyin: "Wǒmen yěxǔ bù néng kòngzhì suǒyǒu jiéguǒ, dànshì kěyǐ xuǎnzé cóng jiéguǒ zhōng xué dào shénme。"
