  quoteTh: "การเติบโตไม่ใช่การเป็นคนใหม่ แต่คือการเข้าใจตัวเองและผู้อื่นมากขึ้น",
  quoteZh: "成长不是变成另一个人，而是更加了解自己，也更加理解别人。",
  quotePinyin: "Chéngzhǎng bú shì biàn chéng lìng yí ge rén, ér shì gèngjiā liǎojiě zìjǐ, yě gèngjiā lǐjiě biérén。"
